import re
import socket
import urllib.parse


def task_func(myString):
    url_pattern = re.compile(
        r'(?i)\b((?:https?://|ftp://|www\.)[^\s<>"\'\]\[{}|\\^`]+|(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}(?:/[^\s<>"\'\]\[{}|\\^`]*)?)'
    )

    def clean_url(url):
        return url.strip().strip(".,;:!?)]}>\'\"")

    def extract_domain(url):
        candidate = url if re.match(r'(?i)^[a-z][a-z0-9+.-]*://', url) else "http://" + url
        parsed = urllib.parse.urlsplit(candidate)
        host = parsed.hostname
        if not host:
            return None
        return host.rstrip(".").lower()

    def resolve_ipv4(domain):
        try:
            ascii_domain = domain.encode("idna").decode("ascii")
            return socket.gethostbyname(ascii_domain)
        except (socket.gaierror, UnicodeError):
            return None

    result = {}
    for match in url_pattern.finditer(myString or ""):
        url = clean_url(match.group(1))
        domain = extract_domain(url)
        if not domain:
            continue
        if domain not in result:
            result[domain] = resolve_ipv4(domain)
    return result
